<?php
require '../config.php';require '../auth.php';require '../helpers.php';require_admin();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';if($action==='delete'){$id=(int)($_POST['id']??0);$stmt=$conn->prepare('DELETE FROM closures WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();}else{$courtId=(int)($_POST['court_id']??0);$date=$_POST['closure_date']??'';$slotRaw=$_POST['time_slot_id']??'';$slotId=$slotRaw===''?null:(int)$slotRaw;$reason=trim($_POST['reason']??'');if($courtId<1||!valid_date($date)||$date<date('Y-m-d')||$reason==='')$error='Enter a valid court, future date and reason.';else{$stmt=$conn->prepare("SELECT COUNT(*) total FROM bookings WHERE court_id=? AND booking_date=? AND status='confirmed' AND (? IS NULL OR time_slot_id=?)");$stmt->bind_param('isii',$courtId,$date,$slotId,$slotId);$stmt->execute();$count=(int)$stmt->get_result()->fetch_assoc()['total'];if($count)$error='Cancel the existing booking(s) before closing this slot.';else{$stmt=$conn->prepare('INSERT INTO closures(court_id,closure_date,time_slot_id,reason) VALUES(?,?,?,?)');$stmt->bind_param('isis',$courtId,$date,$slotId,$reason);$stmt->execute();}}}}
$courts=$conn->query('SELECT c.id,c.court_name,f.facility_name FROM courts c JOIN facilities f ON f.id=c.facility_id ORDER BY f.facility_name,c.court_name')->fetch_all(MYSQLI_ASSOC);$slots=$conn->query('SELECT * FROM time_slots ORDER BY start_time')->fetch_all(MYSQLI_ASSOC);$rows=$conn->query('SELECT x.*,c.court_name,f.facility_name,ts.start_time,ts.end_time FROM closures x JOIN courts c ON c.id=x.court_id JOIN facilities f ON f.id=c.facility_id LEFT JOIN time_slots ts ON ts.id=x.time_slot_id ORDER BY x.closure_date DESC')->fetch_all(MYSQLI_ASSOC);$pageTitle='Closures';require 'partials/header.php';?>
<h1>Facility Closures</h1><?php if($error):?><p class="alert alert-error"><?=htmlspecialchars($error)?></p><?php endif;?><div class="form-card" style="margin-bottom:24px"><h2>Close a Slot or Full Day</h2><form method="post"><input type="hidden" name="action" value="create"><label>Court / Area <select name="court_id" required><?php foreach($courts as $c):?><option value="<?=(int)$c['id']?>"><?=htmlspecialchars($c['facility_name'].' - '.$c['court_name'])?></option><?php endforeach;?></select></label><label>Date <input type="date" name="closure_date" min="<?=date('Y-m-d')?>" required></label><label>Time <select name="time_slot_id"><option value="">Full day</option><?php foreach($slots as $s):?><option value="<?=(int)$s['id']?>"><?=htmlspecialchars(slot_label($s['start_time'],$s['end_time']))?></option><?php endforeach;?></select></label><label>Reason <input name="reason" maxlength="180" placeholder="Maintenance" required></label><button>Add Closure</button></form></div><div class="table-wrap"><table><tr><th>Facility</th><th>Date</th><th>Time</th><th>Reason</th><th>Action</th></tr><?php foreach($rows as $x):?><tr><td><?=htmlspecialchars($x['facility_name'].' - '.$x['court_name'])?></td><td><?=htmlspecialchars(date('d M Y',strtotime($x['closure_date'])))?></td><td><?=$x['time_slot_id']?htmlspecialchars(slot_label($x['start_time'],$x['end_time'])):'Full day'?></td><td><?=htmlspecialchars($x['reason'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=(int)$x['id']?>"><button class="btn-small btn-danger" name="action" value="delete">Remove</button></form></td></tr><?php endforeach;?></table></div><?php require 'partials/footer.php';?>
